function validate(input) {
  const [{ Emails = [] }] = input;
  const ids = new Set();
  for (const [id, email] of Emails) {
    if (id === null) return 'Every row needs an id.';
    if (ids.has(id)) return `id ${id} appears twice in Emails.`;
    ids.add(id);
    if (typeof email !== 'string') return `Row ${id} needs an email.`;
    if (email !== email.toLowerCase()) return `Email ${email} must be lowercase.`;
    const parts = email.split('@');
    if (parts.length !== 2 || !parts[0] || !parts[1]) return `Email ${email} needs exactly one @ between a local part and a domain.`;
  }
  return null;
}

