function generate(rand, size) {
  const locals = ['ana', 'bob', 'kim', 'lee.com', 'ravi', 'sofia', 'wang', 'x'];
  const domains = ['outlook.com', 'yahoo.com', 'gmail.com', 'leetcode.com', 'test.edu', 'example.org', 'mail.com.au', 'box.telecom', 'com.net', 'a.com'];
  const pick = list => list[Math.floor(rand() * list.length)];
  const count = size === 'small' ? Math.floor(rand() * 9) : 2000;
  const used = new Set(), Emails = [];
  while (Emails.length < count) {
    const id = 1 + Math.floor(rand() * (size === 'small' ? 20 : 100000));
    if (used.has(id)) continue;
    used.add(id);
    const local = size === 'small' ? pick(locals) : `${pick(locals)}${Math.floor(rand() * 1000)}`;
    const domain = size === 'small' ? pick(domains) : (rand() < 0.5 ? pick(domains) : `d${Math.floor(rand() * 300)}.${pick(['com', 'org', 'net'])}`);
    Emails.push([id, `${local}@${domain}`]);
  }
  return [{ Emails }];
}
